// Swift engine vs the Python reference on identical .mgpose fixtures
// (generated by Research/motor-rules/tools/make_fixtures.py).

import Foundation
import XCTest
@testable import MotorKit

final class ParityTests: XCTestCase {
    static let root = URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
    static let fixtures = root.appendingPathComponent("Tests/MotorKitTests/Fixtures")
    static let book: MotorRuleBook = {
        let res = root.appendingPathComponent("MoveGrow/Motor/Resources")
        return try! MotorRuleBook(rulesData: Data(contentsOf: res.appendingPathComponent("rules.json")),
                                  sourcesData: Data(contentsOf: res.appendingPathComponent("sources.json")))
    }()

    struct Expected: Decodable {
        struct Row: Decodable {
            let status: String
            let severity: String
            let observed_s: Double?, true_s: Double?, n_episodes: Double?, fraction: Double?, pref_index: Double?
            let median: Double?, arm_asym_index: Double?, largest_cluster: Double?, surrogate_p: Double?
            let denominator_s: Double?, n_events: Int?, first_hz: Double?, first_limbs: [String]?, direction: String?
        }
        let age_weeks: Double?
        let context: String
        let fs: Double
        let rules: [String: Row]
    }

    func fixtureNames() throws -> [String] {
        try FileManager.default.contentsOfDirectory(atPath: Self.fixtures.path)
            .filter { $0.hasSuffix(".mgpose") }.map { String($0.dropLast(7)) }.sorted()
    }

    func testRoundTripBinary() throws {
        let name = try XCTUnwrap(fixtureNames().first)
        let data = try Data(contentsOf: Self.fixtures.appendingPathComponent("\(name).mgpose"))
        let track = try PoseBinary.decode(data)
        let again = try PoseBinary.decode(PoseBinary.encode(track))
        XCTAssertEqual(track.times, again.times)
        XCTAssertEqual(track.xyc.map(\.bitPattern), again.xyc.map(\.bitPattern))
        XCTAssertEqual(track.header, again.header)
    }

    func testParityWithPythonReference() throws {
        var failures: [String] = []
        let engine = MotorEngine(book: Self.book)
        for name in try fixtureNames() {
            let track = try PoseBinary.decode(Data(contentsOf: Self.fixtures.appendingPathComponent("\(name).mgpose")))
            let exp = try JSONDecoder().decode(Expected.self, from: Data(contentsOf: Self.fixtures.appendingPathComponent("\(name).expected.json")))
            let t0 = Date()
            guard let rep = engine.analyze(MotorEngineInput(track: track, ageWeeks: exp.age_weeks, context: exp.context)) else {
                failures.append("\(name): analyze returned nil"); continue
            }
            let ms = Date().timeIntervalSince(t0) * 1000
            if abs(rep.context.fs - exp.fs) > 1e-9 { failures.append("\(name): fs \(rep.context.fs) vs \(exp.fs)") }
            for (rid, row) in exp.rules {
                guard let f = rep.findings.first(where: { $0.ruleID == rid }) else { failures.append("\(name) \(rid): missing"); continue }
                if f.status.rawValue != row.status { failures.append("\(name) \(rid): status \(f.status.rawValue) vs \(row.status)") }
                if f.severity.rawValue != row.severity { failures.append("\(name) \(rid): severity \(f.severity.rawValue) vs \(row.severity)") }
                func close(_ key: String, _ a: Double?, _ b: Double?, tol: Double) {
                    guard let b else { return }
                    guard let a, abs(a - b) <= tol * max(1, abs(b)) else { failures.append("\(name) \(rid): \(key) \(String(describing: a)) vs \(b)"); return }
                }
                close("observed_s", f.metrics["observed_s"], row.observed_s, tol: 0.01)
                close("true_s", f.metrics["true_s"], row.true_s, tol: 0.02)
                close("pref_index", f.metrics["pref_index"], row.pref_index, tol: 0.01)
                close("median", f.metrics["median"], row.median, tol: 0.01)
                close("arm_asym_index", f.metrics["arm_asym_index"], row.arm_asym_index, tol: 0.01)
                close("largest_cluster", f.metrics["largest_cluster"], row.largest_cluster, tol: 0)
                close("surrogate_p", f.metrics["surrogate_p"], row.surrogate_p, tol: 1e-9)
                if let n = row.n_events, f.events.count != n { failures.append("\(name) \(rid): n_events \(f.events.count) vs \(n)") }
                if let hz = row.first_hz { close("first_hz", f.events.first?.hz, hz, tol: 0.01) }
                if let limbs = row.first_limbs, f.events.first?.limbs != limbs { failures.append("\(name) \(rid): limbs \(String(describing: f.events.first?.limbs)) vs \(limbs)") }
                if let d = row.direction, f.direction != d { failures.append("\(name) \(rid): direction \(String(describing: f.direction)) vs \(d)") }
            }
            print(String(format: "%@ analysed in %.0f ms (%d frames)", name, ms, rep.context.frames))
        }
        XCTAssert(failures.isEmpty, failures.joined(separator: "\n"))
    }
}
